CREATE TABLE IF NOT EXISTS gis_ward_evidence_attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_match_id uuid NOT NULL, source_name text NOT NULL, source_url text, evidence_type text NOT NULL, authority_level text NOT NULL DEFAULT 'UNVERIFIED', artifact_sha256 text, excerpt text, state_name text, lga_name text, ward_name text, ward_code text, geometry_verified boolean NOT NULL DEFAULT false, provenance_verified boolean NOT NULL DEFAULT false, verification_status text NOT NULL DEFAULT 'UNVERIFIED', notes text, created_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS gis_ward_evidence_attachments_candidate_idx ON gis_ward_evidence_attachments(candidate_match_id);